seen = set()
tokens_used = 0
for step in range(MAX_STEPS):
    if tokens_used > TOKEN_BUDGET:
        return degrade('เกินงบ token')
    resp = call_model(messages, tools=TOOLS)
    tokens_used += resp.usage.total
    if not resp.tool_calls:
        return resp.content            # stopping condition ปกติ
    sig = signature(resp.tool_calls)   # จับการวนซ้ำ
    if sig in seen:
        return degrade('โมเดลติดวน เรียกซ้ำเดิม')
    seen.add(sig)
    run_and_append(resp.tool_calls, messages)
return degrade('เกิน MAX_STEPS')
